-- =================== VERIFY ROW COUNTS ===================
SELECT 'seasons'           AS tbl,COUNT(*) FROM seasons
UNION ALL SELECT 'tournaments',     COUNT(*) FROM tournaments
UNION ALL SELECT 'teams',           COUNT(*) FROM teams
UNION ALL SELECT 'players',         COUNT(*) FROM players
UNION ALL SELECT 'seeds',           COUNT(*) FROM tournament_seeds
UNION ALL SELECT 'rosters',         COUNT(*) FROM tournament_rosters
UNION ALL SELECT 'bracket_matchups',COUNT(*) FROM bracket_matchups
UNION ALL SELECT 'series',          COUNT(*) FROM series
UNION ALL SELECT 'schedules',       COUNT(*) FROM schedules
UNION ALL SELECT 'games',           COUNT(*) FROM games
UNION ALL SELECT 'quarter_scores',  COUNT(*) FROM quarter_scores
UNION ALL SELECT 'player_stats',    COUNT(*) FROM player_game_stats
UNION ALL SELECT 'awards',          COUNT(*) FROM awards
UNION ALL SELECT 'award_candidates',COUNT(*) FROM award_candidates
UNION ALL SELECT 'championships',   COUNT(*) FROM championships
UNION ALL SELECT 'records',         COUNT(*) FROM records
ORDER BY 1;
